#include <bits/stdc++.h>
using namespace std;

int main() {
    string s;
    getline(cin, s);
    auto starts_with = [](const string& str, const string& prefix) {
        return str.size() >= prefix.size() && str.compare(0, prefix.size(), prefix) == 0;
    };
    auto ends_with = [](const string& str, const string& suffix) {
        return str.size() >= suffix.size() && str.compare(str.size() - suffix.size(), suffix.size(), suffix) == 0;
    };

    if (starts_with(s, "dot") || starts_with(s, "at") || ends_with(s, "at") || ends_with(s, "dot")) {
        auto replace_at_end = [](string& str, const string& suffix, const string& replacement) {
            if (ends_with(str, suffix)) {
                str = str.substr(0, str.size() - suffix.size()) + replacement;
            }
        };

        auto process_s = [&](string& s) {
            if (starts_with(s, "dot")) {
                string t = s.substr(3);
                vector<string> segments;
                size_t start = 0, end;
                while ((end = t.find("dot", start)) != string::npos) {
                    segments.push_back(t.substr(start, end - start));
                    start = end + 3;
                }
                segments.push_back(t.substr(start));
                string combined = "";
                for (size_t i = 0; i < segments.size(); ++i) {
                    combined += segments[i];
                    if (i != segments.size() - 1) combined += ".";
                }
                size_t at_index = combined.find("at");
                string replaced_str = combined.substr(0, at_index) + "@" + combined.substr(at_index + 2);
                string q = "dot" + replaced_str;
                if (!q.empty()) {
                    if (q.back() == '.') {
                        s = q.substr(0, q.size() - 1) + "dot";
                    } else if (q.back() == '@') {
                        s = q.substr(0, q.size() - 1) + "at";
                    } else {
                        s = q;
                    }
                }
            } else if (starts_with(s, "at")) {
                string t = s.substr(2);
                vector<string> segments;
                size_t start = 0, end;
                while ((end = t.find("dot", start)) != string::npos) {
                    segments.push_back(t.substr(start, end - start));
                    start = end + 3;
                }
                segments.push_back(t.substr(start));
                string combined = "";
                for (size_t i = 0; i < segments.size(); ++i) {
                    combined += segments[i];
                    if (i != segments.size() - 1) combined += ".";
                }
                size_t at_index = combined.find("at");
                string replaced_str = combined.substr(0, at_index) + "@" + combined.substr(at_index + 2);
                string q = "at" + replaced_str;
                if (!q.empty()) {
                    if (q.back() == '.') {
                        s = q.substr(0, q.size() - 1) + "dot";
                    } else if (q.back() == '@') {
                        s = q.substr(0, q.size() - 1) + "at";
                    } else {
                        s = q;
                    }
                }
            } else if (ends_with(s, "dot") && !starts_with(s, "dot") && !starts_with(s, "at")) {
                string t = s.substr(0, s.size() - 3);
                vector<string> segments;
                size_t start = 0, end;
                while ((end = t.find("dot", start)) != string::npos) {
                    segments.push_back(t.substr(start, end - start));
                    start = end + 3;
                }
                segments.push_back(t.substr(start));
                string combined = "";
                for (size_t i = 0; i < segments.size(); ++i) {
                    combined += segments[i];
                    if (i != segments.size() - 1) combined += ".";
                }
                size_t at_index = combined.find("at");
                string replaced_str = combined.substr(0, at_index) + "@" + combined.substr(at_index + 2);
                s = replaced_str + "dot";
            } else if (ends_with(s, "at") && !starts_with(s, "dot") && !starts_with(s, "at")) {
                string t = s.substr(0, s.size() - 2);
                vector<string> segments;
                size_t start = 0, end;
                while ((end = t.find("dot", start)) != string::npos) {
                    segments.push_back(t.substr(start, end - start));
                    start = end + 3;
                }
                segments.push_back(t.substr(start));
                string combined = "";
                for (size_t i = 0; i < segments.size(); ++i) {
                    combined += segments[i];
                    if (i != segments.size() - 1) combined += ".";
                }
                size_t at_index = combined.find("at");
                string replaced_str = combined.substr(0, at_index) + "@" + combined.substr(at_index + 2);
                s = replaced_str + "at";
            }
        };

        process_s(s);
        process_s(s);
        process_s(s);
        process_s(s);
        cout << s << "\n";
    } else {
        vector<string> parts;
        size_t start = 0, end;
        while ((end = s.find("dot", start)) != string::npos) {
            parts.push_back(s.substr(start, end - start));
            start = end + 3;
        }
        parts.push_back(s.substr(start));
        string joined = "";
        for (size_t i = 0; i < parts.size(); ++i) {
            joined += parts[i];
            if (i != parts.size() - 1) joined += ".";
        }
        size_t at_index = joined.find("at");
        s = joined.substr(0, at_index) + "@" + joined.substr(at_index + 2);
        cout << s << "\n";
    }
    return 0;
}

